function DreamSpaceLvl1SceneEnter:StartLoadAsync()
    self.loaders = {}
    self.loaders["VCameraBlenderSettings"]  = ResourceModule.LoadBundleAsync("Presets/DreamSpaceVCameraBlenderSettings.asset", nil, true)

    ---
    RoleControllerLoader.ResetAll() 
    RoleControllerLoader.RegistLoadPaths({
        "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab",
        "Arts/Prefab_human/103008_human.prefab",
    })
end



function DreamSpaceLvl1SceneEnter:IsAllLoadingFinished()
    for name,loader in pairs(self.loaders) do 
        if loader.IsSuccess == false then 
            return false 
        end 
    end 

    if RoleControllerLoader.IsAllLoadingFinish() == false then 
        return false 
    end 
    return true
end


function DreamSpaceLvl1SceneEnter:ReleaseAllLoader()
    for _,loader in pairs(self.loaders) do
        loader:Release()
    end
end



function DreamSpaceLvl1SceneEnter:WaitLoadingAndSetting()

    while true  do 
        if self:IsAllLoadingFinished() == true then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end
    ---
    local vcamSettingLoader = self.loaders["VCameraBlenderSettings"]
    if isNotNull(vcamSettingLoader) and vcamSettingLoader.IsSuccess==true and isNotNull(vcamSettingLoader.ResultObject) then 

        local vCameraBlenderSettings = vcamSettingLoader.ResultObject

        self.mCamera = DreamSpaceCamera.GetMainCamera()
        local mCameraBrain  = KTool.GetComponent(self.mCamera.gameObject, typeof(CinemachineBrain))
        mCameraBrain.m_CustomBlends = vCameraBlenderSettings

    else 
        printError("koko - DreamSpaceVCameraBlenderSettings 异步加载失败")
        return
    end 
end






return DreamSpaceLvl1SceneEnter
